        m.update(s.encode('utf8'))
    if lsh.query(m):
        continue  # near-duplicate, skip
    lsh.insert(doc_id, m)

import numpy as np
class DomainMixtureSampler:
    def __init__(self, domain_sizes, temperature=0.3):
        sizes = np.array(list(domain_sizes.values()))
        w = sizes ** temperature
        w /= w.sum()
        self.domains = list(domain_sizes.keys())
        self.weights = w
    def sample(self, n):
        return np.random.choice(self.domains, size=n, p=self.weights)

