import torch.nn as nn
class TokenEmbedding(nn.Module):
    def __init__(self, vocab_size, d_model, padding_idx=0):
        super().__init__()
        self.tok_emb = nn.Embedding(vocab_size, d_model, padding_idx=padding_idx)
        nn.init.normal_(self.tok_emb.weight, mean=0, std=0.02)
        # Weight tying: share with LM head elsewhere
