import torch, torch.nn as nn, torch.nn.functional as F
class MoE(nn.Module):
    def __init__(self, d, d_ff, n_experts=8, top_k=2):
        super().__init__()
        self.router = nn.Linear(d, n_experts, bias=False)
        self.experts = nn.ModuleList([SwiGLU(d, d_ff) for _ in range(n_experts)])
        self.top_k = top_k
    def forward(self, x):
        B, L, D = x.shape
        logits = self.router(x)  # [B,L,E]
        scores, idx = F.softmax(logits, dim=-1).topk(self.top_k, dim=-1)
        out = torch.zeros_like(x)
        for k in range(self.top_k):
            for e in range(len(self.experts)):
                mask = (idx[..., k] == e)
                if mask.any():
                    out[mask] += scores[..., k:k+1][mask] * self.experts[e](x[mask])
        return out
