import torch, torch.nn as nn
class MTPHead(nn.Module):
    def __init__(self, d, vocab, depth=1):
        super().__init__()
        self.blocks = nn.ModuleList([nn.TransformerEncoderLayer(d, 8, 4*d, batch_first=True) for _ in range(depth)])
        self.lm_head = nn.Linear(d, vocab, bias=False)
    def forward(self, h, target_shift):
        # h: hidden states from main model; predict token t+shift
        for b in self.blocks: h = b(h)
        logits = self.lm_head(h)
        return logits  # loss: CE(logits, tokens shifted by target_shift)

