import torch, torch.nn as nn, torch.nn.functional as F
class DeepSeekMoE(nn.Module):
    def __init__(self, d, d_ff_shared, d_ff_routed, n_shared=2, n_routed=64, top_k=6):
        super().__init__()
        self.shared = nn.ModuleList([SwiGLU(d, d_ff_shared) for _ in range(n_shared)])
        self.routed = nn.ModuleList([SwiGLU(d, d_ff_routed) for _ in range(n_routed)])
        self.router = nn.Linear(d, n_routed, bias=False)
        self.bias = nn.Parameter(torch.zeros(n_routed))  # aux-loss-free balancing
        self.top_k = top_k
    def forward(self, x):
        y = sum(s(x) for s in self.shared)  # always-on shared
        logits = self.router(x) + self.bias  # bias NOT a gradient param
        scores, idx = F.softmax(logits, dim=-1).topk(self.top_k, dim=-1)
        # (update self.bias based on expert load, outside gradient)
        for k in range(self.top_k):
            for e in range(len(self.routed)):
                mask = (idx[..., k] == e)
                if mask.any():
                    y[mask] += scores[..., k:k+1][mask] * self.routed[e](x[mask])
        return y

import torch.nn as nn
def init_weights(model, std=0.02):
    for m in model.modules():
        if isinstance(m, nn.Linear):
            nn.init.normal_(m.weight, mean=0, std=std)
            if m.bias is not None: nn.init.zeros_(m.bias)
        elif isinstance(m, nn.Embedding):
            nn.init.normal_(m.weight, mean=0, std=std)
    # Smaller init for LM head to avoid early loss spikes
    nn.init.normal_(model.lm_head.weight, mean=0, std=0.005)
