import torch
def newton_schulz(G, steps=5):
    a, b, c = (3.4445, -4.7750, 2.0315)
    X = G.bfloat16() / (G.norm() + 1e-7)
    for _ in range(steps):
        A = X @ X.T
        B = b * A + c * (A @ A)
        X = a * X + B @ X
    return X
class Muon(torch.optim.Optimizer):
    def __init__(self, params, lr=0.02, momentum=0.95):
        super().__init__(params, {'lr': lr, 'momentum': momentum})
    @torch.no_grad()
    def step(self):
        for g in self.param_groups:
            for p in g['params']:
                s = self.state[p]
                if 'm' not in s: s['m'] = torch.zeros_like(p)
                s['m'].mul_(g['momentum']).add_(p.grad)
                u = newton_schulz(s['m'])
                p.add_(-g['lr'] * u * max(1, p.size(0)/p.size(1))**0.5)

# Lion (sign-only update)
class Lion(torch.optim.Optimizer):
    def __init__(self, params, lr=1e-4, betas=(0.9, 0.99), weight_decay=0.0):
        super().__init__(params, {'lr': lr, 'betas': betas, 'wd': weight_decay})
    @torch.no_grad()
    def step(self):
        for g in self.param_groups:
            b1, b2 = g['betas']
            for p in g['params']:
                s = self.state[p]
                if 'm' not in s: s['m'] = torch.zeros_like(p)
                update = (b1 * s['m'] + (1-b1) * p.grad).sign_()
                s['m'].mul_(b2).add_(p.grad, alpha=1-b2)
                p.mul_(1 - g['lr'] * g['wd']).add_(update, alpha=-g['lr'])

import math
class CosineWithWarmup:
    def __init__(self, opt, warmup_steps, total_steps, min_ratio=0.1):
        self.opt, self.warmup, self.total, self.min = opt, warmup_steps, total_steps, min_ratio
    def step(self, step):
        if step < self.warmup:
            lr = step / max(1, self.warmup)
        else:
            prog = (step - self.warmup) / max(1, self.total - self.warmup)
            lr = self.min + (1 - self.min) * 0.5 * (1 + math.cos(math.pi * prog))
        for g in self.opt.param_groups: g['lr'] = lr * g.get('base_lr', 3e-4)

import math
class WSD:
    def __init__(self, opt, warmup, decay_start, total, min_ratio=0.1):
        self.opt, self.warmup, self.decay_start, self.total, self.min = opt, warmup, decay_start, total, min_ratio
    def step(self, step):
        if step < self.warmup:
            lr = step / max(1, self.warmup)
        elif step < self.decay_start:
            lr = 1.0  # stable
        else:
            prog = (step - self.decay_start) / max(1, self.total - self.decay_start)
            lr = self.min + (1 - self.min) * (1 - prog)  # linear decay
        for g in self.opt.param_groups: g['lr'] = lr * g.get('base_lr', 3e-4)

