import torch, torch.nn as nn
class RewardModel(nn.Module):
    def __init__(self, sft_model):
        super().__init__()
        self.backbone = sft_model  # remove LM head
        self.v_head = nn.Linear(sft_model.config.hidden_size, 1, bias=False)
    def forward(self, input_ids, attention_mask):
        h = self.backbone(input_ids, attention_mask=attention_mask).last_hidden_state
        # Take the last token of each sequence as the reward scalar
        last_idx = attention_mask.sum(-1) - 1
        return self.v_head(h[range(h.size(0)), last_idx]).squeeze(-1)
