import torch
# Manual KV cache (educational)
class KVCache:
    def __init__(self, n_layers, n_kv_heads, head_dim, max_len, dtype=torch.bfloat16):
        self.cache = [None] * n_layers
    def update(self, layer, k_new, v_new):
        if self.cache[layer] is None:
            self.cache[layer] = (k_new, v_new)
        else:
            k, v = self.cache[layer]
            self.cache[layer] = (torch.cat([k, k_new], dim=-2),
                                torch.cat([v, v_new], dim=-2))
        return self.cache[layer]
