import torch, torch.nn as nn
class PRM(nn.Module):
    def __init__(self, base_model):
        super().__init__()
        self.backbone = base_model
        self.score_head = nn.Linear(base_model.config.hidden_size, 1)
    def step_scores(self, input_ids, step_end_positions):
        h = self.backbone(input_ids).last_hidden_state
        # Score each step by reading the last token of each step
        return self.score_head(h[range(h.size(0)), step_end_positions])
