import torch.nn as nn
class iRoPEBlock(nn.Module):
    def __init__(self, d, h, use_rope=True, theta=500000):
        super().__init__()
        self.attn = Attention(d, h)
        self.use_rope = use_rope
        if use_rope:
            self.rope = RoPE(d//h, theta=theta)
    def forward(self, x):
        q, k, v = self.attn.qkv(x).chunk(3, dim=-1)
        if self.use_rope:
            q, k = self.rope(q), self.rope(k)  # rotate
        # else: no positional encoding (NoPE) - rely on causal mask
        return x + self.attn.out(F.scaled_dot_product_attention(q,k,v,is_causal=True))
# Stack: [RoPE, NoPE, NoPE, NoPE, RoPE, NoPE, NoPE, NoPE, ...]  1:3 ratio

import torch, torch.nn as nn, torch.nn.functional as F
class SigmoidMoE(nn.Module):
    def __init__(self, d, d_ff, n_experts=64, top_k=6):
        super().__init__()
        self.router = nn.Linear(d, n_experts, bias=False)
        self.experts = nn.ModuleList([SwiGLU(d, d_ff) for _ in range(n_experts)])
        self.top_k = top_k
    def forward(self, x):
        B, L, D = x.shape
        # Sigmoid (not softmax!) - independent per-expert scores
        scores = torch.sigmoid(self.router(x))  # [B, L, E], each in [0,1]
        topk_scores, topk_idx = scores.topk(self.top_k, dim=-1)  # top-k by sigmoid
        out = torch.zeros_like(x)
        for k in range(self.top_k):
            for e in range(len(self.experts)):
                mask = (topk_idx[..., k] == e)
                if mask.any():
                    out[mask] += topk_scores[..., k:k+1][mask] * self.experts[e](x[mask])
        return out
